/// @title Module for hanlding withdraw collateral request from user
/// @notice User can withdarw collateral as long as the obligation risk level is lower than 1
module protocol::repay;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct RepayEvent has copy, drop {
    repayer: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,
    amount: u64,

    total_borrow: Decimal,
    borrow_index: Decimal,

    refund: u64,
    time: u64,
}

public fun repay_on_behalf<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_id: ID,
    market: &mut Market<MarketType>,
    coin: Coin<CoinType>,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let repay_amount = coin.value();
    let (refund, borrow_index, total_borrow) = market.handle_repay(
        obligation_id,
        coin,
        now,
        ctx,
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_id,
        total_borrow.floor(),
        clock
    );

    emit(RepayEvent {
        repayer: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_id,

        asset: type_name::with_defining_ids<CoinType>(),
        amount: repay_amount,
        borrow_index,
        total_borrow,

        refund: refund.value(),
        time: now,
    });

    refund
}

public fun repay_coin_refund<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin: Coin<CoinType>,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    repay_on_behalf<MarketType, CoinType>(app, obligation_owner_cap.id(), market, coin, clock, ctx)
}

#[allow(lint(self_transfer))]
public fun repay<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin: Coin<CoinType>,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let refund = repay_coin_refund(app, obligation_owner_cap, market, coin, clock, ctx);

    // Transfer the remaining asset back to the sender if any
    let refund_amount = refund.value();
    if (refund_amount == 0) {
        coin::destroy_zero(refund);
    } else {
        transfer::public_transfer(refund, ctx.sender());
    };
}

module protocol::liquidity_mining;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::coin::Coin;
use sui::event::emit;

use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;

use protocol::app::ProtocolApp;

public struct RewardClaimedEvent has copy, drop {
    who: address,

    market: TypeName,
    obligation: ID,

    coin_type: TypeName,
    reward_coin_type: TypeName,

    reward_amount: u64,

    time: u64,
}


public fun claim_reward_as_coin<MarketType, CoinType, RewardCoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,

    reward_type: u8,
    reward_index: u64,

    clock: &Clock,
    ctx: &mut TxContext,
): Coin<RewardCoinType>{
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    let claimed_reward = miner.claim_rewards<MarketType, CoinType, RewardCoinType>(
        reward_type,
        obligation_owner_cap.id(),
        clock,
        reward_index
    );

    emit(RewardClaimedEvent {
        who: ctx.sender(),
        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),
        coin_type: type_name::with_defining_ids<CoinType>(),
        reward_coin_type: type_name::with_defining_ids<RewardCoinType>(),
        reward_amount: claimed_reward.value(),
        time: clock.timestamp_ms() / 1000,
    });
    claimed_reward.into_coin(ctx)
}

#[allow(lint(self_transfer))]
public fun claim_reward<MarketType, CoinType, RewardCoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,

    reward_type: u8,
    reward_index: u64,

    clock: &Clock,
    ctx: &mut TxContext,
) {
    let claimed_reward = claim_reward_as_coin<MarketType, CoinType, RewardCoinType>(
        app, market, obligation_owner_cap, reward_type, reward_index, clock, ctx
    );
    transfer::public_transfer(claimed_reward, ctx.sender());
}

