     1→// refactor obligation to better handle operations
     2→module protocol::obligation;
     3→
     4→use protocol::ctoken::CToken;
     5→use protocol::ctoken_table::{Self, CTokenTable};
     6→use protocol::debt::{Self, Debt};
     7→use protocol::error;
     8→use std::type_name::{Self, TypeName};
     9→use sui::balance::Balance;
    10→use protocol::wit_table::{Self, WitTable};
    11→use math::float::Decimal;
    12→
    13→public struct ObligationOwnerCap has key, store {
    14→    id: UID,
    15→    obligation_id: ID,
    16→
    17→    // redundant fields, but makes query slightly easier
    18→    market_type: TypeName,
    19→    market_id: ID,
    20→}
    21→
    22→public struct Obligation<phantom MarketType> has key, store {
    23→    id: UID,
    24→    // with market id, no need to track version
    25→    lending_market_id: ID,
    26→    debts: WitTable<ObligationDebts, TypeName, Debt>,
    27→    ctokens: CTokenTable,
    28→
    29→    emode_group: u8,
    30→}
    31→
    32→public fun id(self: &ObligationOwnerCap): ID {
    33→    self.obligation_id
    34→}
    35→
    36→public(package) fun emode_group<MarketType>(self: &Obligation<MarketType>): u8 {
    37→    self.emode_group
    38→}
    39→
    40→public(package) fun debts<MarketType>(
    41→    self: &Obligation<MarketType>,
    42→): &WitTable<ObligationDebts, TypeName, Debt> {
    43→    &self.debts
    44→}
    45→
    46→public(package) fun market_id<MarketType>(self: &Obligation<MarketType>): ID {
    47→    self.lending_market_id
    48→}
    49→
    50→public(package) fun new<MarketType>(
    51→    lending_market_id: ID,
    52→    emode_group: u8,
    53→    ctx: &mut TxContext,
    54→): (Obligation<MarketType>, ObligationOwnerCap) {
    55→    let obligation = Obligation {
    56→        id: object::new(ctx),
    57→        lending_market_id,
    58→        debts: wit_table::new(ObligationDebts {}, true, ctx),
    59→        ctokens: ctoken_table::new(ctx),
    60→        emode_group,
    61→    };
    62→
    63→    let cap = ObligationOwnerCap {
    64→        id: object::new(ctx),
    65→        obligation_id: object::id(&obligation),
    66→        market_type: type_name::with_defining_ids<MarketType>(),
    67→        market_id: lending_market_id,
    68→    };
    69→    (obligation, cap)
    70→}
    71→
    72→public(package) fun accrue_interest<MarketType>(
    73→    self: &mut Obligation<MarketType>,
    74→    name: TypeName,
    75→    asset_borrow_index: Decimal,
    76→): &mut Debt {
    77→    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
    78→    debt.accrue_interest(asset_borrow_index);
    79→    debt
    80→}
    81→
    82→public(package) fun deposit_ctoken<MarketType, CoinType>(
    83→    self: &mut Obligation<MarketType>,
    84→    ctoken: Balance<CToken<MarketType, CoinType>>,
    85→) {
    86→    assert!(
    87→        !self.debts.contains(type_name::with_defining_ids<CoinType>()),
    88→        error::obligation_deposit_borrowed_asset(),
    89→    );
    90→    if (!self.ctokens.is_supporting_collateral<MarketType, CoinType>()) {
    91→        self.ctokens.support_collateral_token<MarketType, CoinType>();
    92→    };
    93→    self.ctokens.join_ctoken(ctoken);
    94→}
    95→
    96→public(package) fun withdraw_ctokens<MarketType, CoinType>(
    97→    self: &mut Obligation<MarketType>,
    98→    amount: u64,
    99→): Balance<CToken<MarketType, CoinType>> {
   100→    assert!(
   101→        self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   102→        error::obligation_withdraw_no_deposit(),
   103→    );
   104→    self.ctokens.split_ctoken<MarketType, CoinType>(amount)
   105→}
   106→
   107→/// Try borrow the asset, increase the debt. Returns the latest asset debt.
   108→public(package) fun try_borrow_asset<MarketType, CoinType>(
   109→    self: &mut Obligation<MarketType>,
   110→    amount: u64,
   111→    asset_borrow_index: Decimal,
   112→): Decimal {
   113→    let name = type_name::with_defining_ids<CoinType>();
   114→
   115→    let amount = math::float::from(amount);
   116→
   117→    if (!self.debts.contains(type_name::with_defining_ids<CoinType>())) {
   118→        // no borrow before, init borrow
   119→
   120→        // do not allow borrowing of collateral asset, mess up book keeping
   121→        assert!(
   122→            !self.ctokens.is_supporting_collateral<MarketType, CoinType>(),
   123→            error::obligation_borrow_collateral_asset(),
   124→        );
   125→
   126→        wit_table::add(
   127→            ObligationDebts {},
   128→            &mut self.debts,
   129→            name,
   130→            debt::new(amount, asset_borrow_index),
   131→        );
   132→
   133→        return amount
